from datetime import date, timedelta

_WEEKDAYS = ("MO", "TU", "WE", "TH", "FR", "SA", "SU")


def recur(start: str, rule: str, count: int) -> list[str]:
    def nth_weekday(year: int, month: int, n: int, wd: int):
        if month == 12:
            month_end = date(year + 1, 1, 1) - timedelta(days=1)
        else:
            month_end = date(year, month + 1, 1) - timedelta(days=1)
        if n == -1:
            return month_end - timedelta(days=(month_end.weekday() - wd) % 7)
        first = date(year, month, 1)
        day = first + timedelta(days=(wd - first.weekday()) % 7 + (n - 1) * 7)
        if day.month != month:
            return None
        return day

    y, m, d = (int(x) for x in start.split("-"))
    start_d = date(y, m, d)
    parts = rule.split()
    kind = parts[0]
    step = int(parts[1])
    out: list[str] = []

    if kind == "DAILY":
        cur = start_d
        for _ in range(count):
            out.append(cur.isoformat())
            cur += timedelta(days=step)
        return out

    if kind == "WEEKLY":
        wanted = {_WEEKDAYS.index(code) for code in parts[2].split(",")}
        monday = start_d - timedelta(days=start_d.weekday())
        week = 0
        while len(out) < count:
            base = monday + timedelta(days=7 * week)
            for i in range(7):
                cur = base + timedelta(days=i)
                if cur >= start_d and cur.weekday() in wanted:
                    out.append(cur.isoformat())
                    if len(out) == count:
                        return out
            week += step
        return out

    if kind == "MONTHLY" and len(parts) == 3:
        dom = int(parts[2])
        year, month = start_d.year, start_d.month
        idx = 0
        while len(out) < count:
            abs_m = month - 1 + idx
            yy, mm = year + abs_m // 12, abs_m % 12 + 1
            if dom == -1:
                cur = date(yy + (mm == 12), 1 if mm == 12 else mm + 1, 1) - timedelta(days=1)
            else:
                try:
                    cur = date(yy, mm, dom)
                except ValueError:
                    cur = None
            if cur is not None and cur >= start_d:
                out.append(cur.isoformat())
            idx += step
        return out

    if kind == "MONTHLY":
        n = int(parts[2])
        wd = _WEEKDAYS.index(parts[3])
        year, month = start_d.year, start_d.month
        idx = 0
        while len(out) < count:
            abs_m = month - 1 + idx
            yy, mm = year + abs_m // 12, abs_m % 12 + 1
            cur = nth_weekday(yy, mm, n, wd)
            if cur is not None and cur >= start_d:
                out.append(cur.isoformat())
            idx += step
        return out

    mm, dd = (int(x) for x in parts[2].split("-"))
    year = start_d.year
    idx = 0
    while len(out) < count:
        try:
            cur = date(year + idx, mm, dd)
        except ValueError:
            cur = None
        if cur is not None and cur >= start_d:
            out.append(cur.isoformat())
        idx += step
    return out
